// Timing configurations (in seconds)
const UNIT_DURATION = 0.04; // The length of one "dot" (e.g., 100ms)
const VOL_ON = 0.2, VOL_OFF = 0.05;
const DOT_TIME = UNIT_DURATION;
const DASH_TIME = UNIT_DURATION * 3;
const INTRA_CHARACTER_GAP = UNIT_DURATION; // Gap between dots/dashes of same letter
const LETTER_GAP = UNIT_DURATION * 3;       // Gap between letters
const WORD_GAP = UNIT_DURATION * 7;         // Gap between words

const morseCodes = {
  // Letters
  'a': '.-',   'b': '-...', 'c': '-.-.', 'd': '-..',  'e': '.', 
  'f': '..-.', 'g': '--.',  'h': '....', 'i': '..',   'j': '.---', 
  'k': '-.-',  'l': '.-..', 'm': '--',   'n': '-.',   'o': '---', 
  'p': '.--.', 'q': '--.-', 'r': '.-.',  's': '...',  't': '-', 
  'u': '..-',  'v': '...-', 'w': '.--',  'x': '-..-', 'y': '-.--', 
  'z': '--..',

  // Digits
  '1': '.----', '2': '..---', '3': '...--', '4': '....-', '5': '.....',
  '6': '-....', '7': '--...', '8': '---..', '9': '----.', '0': '-----',

  // Punctuation Marks
  '.': '.-.-.-', ',': '--..--', '?': '..--..', "'": '.----.', '!': '-.-.--',
  '/': '-..-.',  '(': '-.--.',  ')': '-.--.-', '&': '.-...',  ':': '---...',
  ';': '-.-.-.', '=': '-...-',  '+': '.-.-.',  '-': '-....-', '_': '..--.-',
  '"': '.-..-.', '$': '...-..-', '@': '.--.-.'
};

// Automatically create a reverse lookup object for decoding
const morseToChar = {};
for (let key in morseCodes) {
  morseToChar[morseCodes[key]] = key;
}


function encodeMorse(text) {
  let words = text.toLowerCase().split(' ');
  let encodedWords = words.map(word => {
    return word
      .split('')
      .map(char => morseCodes[char] || '') // Fallback to empty string if char not found
      .filter(code => code !== '')         // Filter out unmappable characters
      .join(' ');                          // Separate characters with a space
  });

  return encodedWords.join('   '); // Separate words with 3 spaces
}


function decodeMorse(morseText) {
  let morseWords = morseText.split('   '); // Split by word separator
  let decodedWords = morseWords.map(word => {
    return word
      .split(' ')                          // Split by letter separator
      .map(code => morseToChar[code] || '') // Fallback to empty string if code not found
      .join('');
  });

  return decodedWords.join(' '); // Rejoin words with a space
}


function playMorseAudio(morseText) {
  // 1. Create the audio context and oscillator
  const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
  const oscillator = audioCtx.createOscillator();
  const gainNode = audioCtx.createGain();

  oscillator.type = 'sine';
  const note = random(240, 300);
  oscillator.frequency.setValueAtTime(note, audioCtx.currentTime); // 600Hz tone

  // Connect nodes: Oscillator -> Gain (Volume) -> Speakers
  oscillator.connect(gainNode);
  gainNode.connect(audioCtx.destination);

  // Start the oscillator silently
  gainNode.gain.setValueAtTime(0, audioCtx.currentTime);
  oscillator.start();

  let time = audioCtx.currentTime;

  // 2. Parse the Morse string and schedule the sound
  // Split into words by 3 spaces
  var words = morseText.split('   '); 

  words.forEach((word, wordIndex) => {
    let letters = word.split(' '); // Split into letters by 1 space

    letters.forEach((letter, letterIndex) => {
      let symbols = letter.split(''); // Split into '.' or '-'

      symbols.forEach((symbol) => {
        let duration = (symbol === '.') ? DOT_TIME : DASH_TIME;

        // Turn volume UP (Beep start)
        gainNode.gain.setValueAtTime(VOL_ON, time);
        time += duration;

        // Turn volume DOWN (Beep stop)
        gainNode.gain.setValueAtTime(VOL_OFF, time);
        time += INTRA_CHARACTER_GAP;
      });

      // Finished a letter (subtract intra-gap to prevent double padding)
      time += (LETTER_GAP - INTRA_CHARACTER_GAP);
    });

    // Finished a word
    time += (WORD_GAP - LETTER_GAP);
  });

  // Stop the oscillator completely after the last sound finishes
  oscillator.stop(time);
}

