let fipF = false;
let S, msg = "Radioactivity";
const RGBs = ["red", "green", "blue"];

function setup() {
	createCanvas(windowWidth, windowHeight, fipF ? WEBGL : P2D);
	S = max(width, height) * 0.9;
	msg = encodeMorse(msg);
	if (fipF) fipF = createFilterShader(fip.halftone); // fip.duoTone
	// playMorseAudio(msg);
}

function mousePressed() {
	if ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > width * 0.1) {
		playMorseAudio(msg);
	}
}

function draw() {
	// if ((frameCount) % 250 === 0) playMorseAudio(msg);

	const t = millis() / 1000;
	const cg = sin(t) * 16 + 16;
	const cb = cos(t) * 16 + 16;
	const cr = constrain(tan(t), -1, 1) * 16 + 16;
	const CLRS = [cr, cg, cb, 64];
	const BG = color(...CLRS);
	background(BG);
	if (!fipF) translate(width / 2, height / 2);
	const a = t * 0.5;
	rotate(a)

	noStroke();
	fill(255, 192);
	// pulsing inner core
	circle(0, 0, S/10 + sin(t)*S/30);
	circle(0, 0, S/10 + cos(t)*S/30);

	for (let i = 0; i < 3; i++) {
		noFill();
		stroke(240);
		strokeWeight(S / 60);
		ellipse(0, 0, S, S/3);


		const x = cos(a*4+i*TAU/3) * S/2;
		const y = sin(a*4+i*TAU/3) * S/6;
		stroke(BG);
		strokeWeight(S/60);
		fill(RGBs[i])
		circle(x, y, S/15)

		rotate(TAU / 3);
	}

	if (fipF) {	
		fipF.setUniform('cellSize', 15.0);
		fipF.setUniform('threshold', 0.25);
		fipF.setUniform('tone1', [0.8627, 0.6275, 0.0]);
		fipF.setUniform('tone2', [0.4157, 0.0118, 0.5647]);
		filter(fipF);
	}
}
